pub fn ftNs_SpecialAirHiRebound_Coll<'a>(ctx: &'a Ctx, gobj: HSD_GObj<'a>) {
    let __frame = ctx.stack_frame(0x28);
    let mut gobj = gobj;
    let mut fp: Fighter<'a> =
        (Handle::cast::<Fighter<'a>>(inl_HSD_GObjGetUserData_unfused(ctx, gobj)));
    if fns::ft_CheckGroundAndLedge(ctx, gobj, 0_i32) == 1_i32 {
        (fp).self_vel().set_z(0.0);
        (fp).self_vel().set_y(0.0);
        (fp).self_vel().set_x(0.0);
        inl_ftNs_SpecialHiStopGFX_unfused(ctx, gobj);
        fns::ftPartSetRotX(ctx, fp, 0_i32, 0.0);
        fns::ftCo_80097D40(ctx, gobj);
        return;
    }
    if fns::ftCliffCommon_80081298(ctx, gobj) != 0_i32 {
        fns::ftCliffCommon_80081370(ctx, gobj);
    }
}

