fn inl_check_distance<'a>(ctx: &'a Ctx, pos: Vec<'a>, pair: Vec<'a>) -> i32 {
    let mut pos = pos;
    let mut pair = pair;
    if ((if (fp::fsubs((pos).x(), (pair).x())) < fp::frsp(0_i32 as f64) {
        fp::fneg((fp::fsubs((pos).x(), (pair).x())))
    } else {
        (fp::fsubs((pos).x(), (pair).x()))
    }) < 8.333333015441895)
        && ((if (fp::fsubs((pos).y(), (pair).y())) < fp::frsp(0_i32 as f64) {
            fp::fneg((fp::fsubs((pos).y(), (pair).y())))
        } else {
            (fp::fsubs((pos).y(), (pair).y()))
        }) < 12.333333015441895)
    {
        return 1_i32;
    }
    return 0_i32;
}

